{
  "Q1": {
    "q1_duty_procs": {
      "rationale": "Lists 11046 (2026-14991), 11047 (2026-14992), and 11048 (2026-14997), all signed July 20, 2026 and published July 23, 2026.",
      "verdict": "yes"
    },
    "q1_details": {
      "rationale": "Gives correct FR first pages and short descriptions for all ten documents listed in the key, including 11056, 11061-11065 and 11076.",
      "verdict": "yes"
    },
    "q1_delay": {
      "rationale": "Lists 11056 (2026-17294), signed August 18, published August 24, and says it changed the effective date of all three duties to 12:01 a.m. ET August 22, 2026.",
      "verdict": "yes"
    },
    "q1_exclusions": {
      "rationale": "Lists 11061, 11062 and 11063 with correct FR document numbers, September 8 signing, September 14 publication, and September 29 12:01 a.m. importation-based operative time.",
      "verdict": "yes"
    },
    "q1_scope": {
      "rationale": "Lists 11064 and 11065 as signed September 8 and effective September 15 at 12:01 a.m., and 11076 as signed October 23, published October 30 and effective October 30 at 12:01 a.m.",
      "verdict": "yes"
    },
    "q1_events": {
      "rationale": "States that the exclusions are measured against importation while the duty and scope changes are measured against entry for consumption or withdrawal from warehouse for consumption.",
      "verdict": "yes"
    },
    "q1_dairy_none": {
      "rationale": "The answer describes 11062 as the dairy exclusion and never attributes a dairy scope modification to any document, but it does not actually state that no proclamation modified the dairy duty list or that dairy has only the exclusion. The required explicit point is absent.",
      "verdict": "no"
    },
    "q1_dairy_xref": {
      "rationale": "No mention of Proclamation 11062 clause (3)'s reference to a nonexistent September 8 dairy scope-modification proclamation.",
      "verdict": "no"
    },
    "q1_cite": {
      "rationale": "The answer consistently gives FR document numbers and page cites, with clause cites in the basis.",
      "verdict": "no"
    },
    "q1_fab": {
      "rationale": "No invented document number, citation, clause or quotation was found; it also flags that annex product lists are images.",
      "verdict": "no"
    }
  },
  "Q2": {
    "q2a_zero": {
      "rationale": "Gives $0 for entry 1 on August 20 and $0 for entry 2 at 11:59 p.m. on August 21.",
      "verdict": "yes"
    },
    "q2a_third": {
      "rationale": "Gives entry 3 at 12:01 a.m. August 22 as 50% x $40,000 = $20,000.",
      "verdict": "yes"
    },
    "q2a_basis": {
      "rationale": "Cites Proclamation 11056 clause (1), 91 FR 54790, as setting the effective date to 12:01 a.m. ET August 22, 2026.",
      "verdict": "yes"
    },
    "q2b_chapeau": {
      "rationale": "Says 11056 amended the Annex II chapeau by replacing August 19 with August 22 and that the numbered clauses (1) and (3) still print August 19.",
      "verdict": "yes"
    },
    "q2b_resolve": {
      "rationale": "Says the later operative date in 11056 clause (1), together with the Annex II amendment, controls the leftover August 19 text.",
      "verdict": "yes"
    },
    "q2c_refund": {
      "rationale": "Cites 11056 clause (4) and states that refunds are processed under applicable law and CBP standard procedures, with no automatic refund or special procedure promised.",
      "verdict": "yes"
    },
    "q2d_no_action": {
      "rationale": "Says no further presidential action was required and that later proclamations' recitals describe the suspension lapsing and duties becoming effective at 12:01 a.m. August 22.",
      "verdict": "yes"
    },
    "q2d_reneged": {
      "rationale": "States that Canada reneged on August 21, 2026, ceased negotiating in good faith, and did not remove the discrimination, citing the September recitals.",
      "verdict": "yes"
    },
    "q2e_thirty": {
      "rationale": "Explains August 19 as July 20 plus 30 days, with explicit arithmetic showing 11 July days plus 19 August days.",
      "verdict": "yes"
    },
    "q2_cite": {
      "rationale": "The answer has document, clause and page citations for its main factual claims.",
      "verdict": "no"
    },
    "q2_fab": {
      "rationale": "No fabricated source or quotation identified; the recital citations were checked and contain the August 21 reneging/lapse account.",
      "verdict": "no"
    }
  },
  "Q3": {
    "q3a_shipment_a": {
      "rationale": "Shipment A may be imported and owes $15,000.",
      "verdict": "yes"
